INSERT INTO trechos (id, texto, publico, macronarrativa, pauta, tipo, forca, link, pagina) VALUES ('D12-TR-209-mb', 'O Brasil deixa de ser apenas problema, disputa ou propaganda e passa a aparecer como uma experiência comum, afetiva e reconhecível.', 'mulheres beneficiárias', 'brasil e pertencimento', 'brasil cotidiano', 'achado', 'indício', NULL, '33'), ('D12-TR-210-mb', 'No estado final, há conjunção com um orgulho nacional mais maduro: é possível amar o Brasil apesar das falhas e se projetar em um país que ainda pode melhorar.', 'mulheres beneficiárias', 'brasil e pertencimento', 'orgulho e identidade nacional', 'achado', 'indício', NULL, '34'), ('D12-TR-211-mb', 'O reencantamento não apaga o desencanto, mas o reorganiza em esperança possível.', 'mulheres beneficiárias', 'brasil e pertencimento', 'futuro possível', 'achado', 'indício', NULL, '34'), ('D12-TR-212-mb', 'O território "O Brasil real que a gente ama" é transversal e parte do sentimento atual de amor pelo país apesar das falhas, ancorado em cotidiano, família, comida, humor, cuidado, trabalho e território.', 'mulheres beneficiárias', 'brasil e pertencimento', 'brasil cotidiano', 'achado', 'indício', NULL, '35'), ('D12-TR-214-mb', 'O território "Potências que fazem acreditar" é transversal e reencanta ao mostrar capacidades reconhecíveis do país: SUS, PIX, ciência, esporte, cinema, cultura, mascotes e reconhecimento internacional.', 'mulheres beneficiárias', 'brasil e pertencimento', 'potências do país', 'achado', 'indício', NULL, '35'), ('D12-TR-216-mb', 'O território "Pertencimento regional, orgulho nacional" é forte para o Nordeste e para identidades territoriais, e apresenta o país como soma de muitos Brasis: sotaques, estados, comidas, festas, paisagens e formas de viver.', 'mulheres beneficiárias', 'brasil e pertencimento', 'pertencimento regional', 'achado', 'indício', NULL, '35'), ('D12-TR-218-mb', 'O território "Futuro possível, não país perfeito" é transversal, especialmente para descrentes e indecisas, e organiza o orgulho como esperança concreta, não como propaganda ou negação das falhas.', 'mulheres beneficiárias', 'brasil e pertencimento', 'futuro possível', 'achado', 'indício', NULL, '35'), ('D12-TR-220-mb', 'Os territórios partem do sentimento atual pelo Brasil real, reconhecendo falhas sem romper o vínculo afetivo, e chegam à ideia de um futuro possível, em que o país não precisa ser perfeito para voltar a mobilizar esperança.', 'mulheres beneficiárias', 'brasil e pertencimento', 'futuro possível', 'achado', 'indício', NULL, '35'), ('D12-TR-221-mb', 'O amor pelo Brasil nasce do país vivido: família, comida, humor, cuidado, trabalho e território, mesmo com falhas.', 'mulheres beneficiárias', 'brasil e pertencimento', 'brasil cotidiano', 'achado', 'indício', NULL, '36'), ('D12-TR-222-mb', 'A mulher aparece como sujeito que reconhece as dificuldades, mas preserva vínculo afetivo com o país.', 'mulheres beneficiárias', 'brasil e pertencimento', 'orgulho e identidade nacional', 'achado', 'indício', NULL, '36'), ('D12-TR-224-mb', 'O Brasil aparece como problema, disputa ou decepção.', 'mulheres beneficiárias', 'brasil e pertencimento', 'confiança nas instituições', 'achado', 'indício', NULL, '36'), ('D12-TR-226-mb', 'No estado final, é possível amar o Brasil sem fingir que ele é perfeito.', 'mulheres beneficiárias', 'brasil e pertencimento', 'orgulho e identidade nacional', 'achado', 'indício', NULL, '36'), ('D12-TR-227-mb', 'O orgulho se reacende quando o país mostra capacidades concretas e reconhecíveis.', 'mulheres beneficiárias', 'brasil e pertencimento', 'potências do país', 'achado', 'indício', NULL, '37'), ('D12-TR-228-mb', 'A mulher aparece como cidadã que se reconhece em conquistas coletivas que também fazem parte da sua vida.', 'mulheres beneficiárias', 'brasil e pertencimento', 'potências do país', 'achado', 'indício', NULL, '37'), ('D12-TR-232-mb', 'No estado final, o Brasil volta a parecer potente, reconhecível e digno de orgulho.', 'mulheres beneficiárias', 'brasil e pertencimento', 'orgulho e identidade nacional', 'achado', 'indício', NULL, '37'), ('D12-TR-233-mb', 'O Brasil ganha força quando aparece como soma de muitos Brasis.', 'mulheres beneficiárias', 'brasil e pertencimento', 'pertencimento regional', 'achado', 'indício', NULL, '38'), ('D12-TR-234-mb', 'A mulher aparece como sujeito de território: reconhece-se no sotaque, na comida, na cultura, nas festas e no modo de viver de onde vem.', 'mulheres beneficiárias', 'brasil e pertencimento', 'pertencimento regional', 'achado', 'indício', NULL, '38'), ('D12-TR-238-mb', 'No estado final, amar o Brasil passa por se reconhecer no próprio território.', 'mulheres beneficiárias', 'brasil e pertencimento', 'pertencimento regional', 'achado', 'indício', NULL, '38'), ('D12-TR-239-mb', 'Reencantar não é negar problemas, mas mostrar que ainda há potência para melhorar.', 'mulheres beneficiárias', 'brasil e pertencimento', 'futuro possível', 'achado', 'indício', NULL, '39'), ('D12-TR-240-mb', 'A mulher aparece como sujeito de esperança lúcida: critica o presente, mas pode se projetar em um país possível.', 'mulheres beneficiárias', 'brasil e pertencimento', 'futuro possível', 'achado', 'indício', NULL, '39'), ('D12-TR-242-mb', 'O desencanto faz o Brasil parecer travado ou perdido.', 'mulheres beneficiárias', 'brasil e pertencimento', 'confiança nas instituições', 'achado', 'indício', NULL, '39'), ('D12-TR-244-mb', 'No estado final, o país não precisa ser perfeito para voltar a mobilizar esperança.', 'mulheres beneficiárias', 'brasil e pertencimento', 'futuro possível', 'achado', 'indício', NULL, '39'), ('D01-TR-086-mb', 'A associação do brasileiro a "preguiçoso" é rejeitada com força.', 'mulheres beneficiárias', 'brasil e pertencimento', 'orgulho e identidade nacional', 'afasta', NULL, NULL, '32'), ('D01-TR-087-mb', 'A violência contra a mulher aparece como mancha na autoimagem coletiva do país.', 'mulheres beneficiárias', 'brasil e pertencimento', 'violência contra a mulher', 'afasta', NULL, NULL, '32'), ('D12-TR-205-mb', 'Quando o orgulho nacional vira propaganda ou patriotismo abstrato, perde credibilidade.', 'mulheres beneficiárias', 'brasil e pertencimento', 'orgulho e identidade nacional', 'afasta', NULL, NULL, '33'), ('D12-TR-230-mb', 'O orgulho nacional soa abstrato ou capturado pela política.', 'mulheres beneficiárias', 'brasil e pertencimento', 'país em disputa', 'afasta', NULL, NULL, '37'), ('D12-TR-236-mb', 'O Brasil aparece como símbolo nacional genérico.', 'mulheres beneficiárias', 'brasil e pertencimento', 'orgulho e identidade nacional', 'afasta', NULL, NULL, '38'), ('D12-TR-022-mb', 'O orgulho nacional precisa evitar idealização e polarização: falar do Brasil vivido, reconhecer falhas e valorizar potências concretas como SUS, PIX, ciência, esporte, cultura, humor, território e acolhimento.', 'mulheres beneficiárias', 'brasil e pertencimento', 'potências do país', 'funciona', NULL, NULL, '8'), ('D12-TR-174-mb', 'O orgulho pelo Brasil funciona quando reconhece o país real: potência, falhas e pertencimento cotidiano.', 'mulheres beneficiárias', 'brasil e pertencimento', 'orgulho e identidade nacional', 'funciona', NULL, NULL, '30'), ('D12-TR-177-mb', 'A comunicação deve evitar capturar o Brasil para um lado.', 'mulheres beneficiárias', 'brasil e pertencimento', 'país em disputa', 'funciona', NULL, NULL, '30'), ('D12-TR-178-mb', 'O caminho é falar de pertencimento cotidiano.', 'mulheres beneficiárias', 'brasil e pertencimento', 'brasil cotidiano', 'funciona', NULL, NULL, '30'), ('D12-TR-180-mb', 'Esporte, SUS, ciência, cinema, PIX, humor, mascotes e reconhecimento internacional aparecem como figuras de potência brasileira.', 'mulheres beneficiárias', 'brasil e pertencimento', 'potências do país', 'funciona', NULL, NULL, '30'), ('D12-TR-181-mb', 'Brasil Core deve falar de potência coletiva sem transformar dificuldade em virtude.', 'mulheres beneficiárias', 'brasil e pertencimento', 'potências do país', 'funciona', NULL, NULL, '30'), ('D12-TR-184-mb', 'A narrativa mais crível é o amor apesar das falhas, não a fantasia de um país perfeito.', 'mulheres beneficiárias', 'brasil e pertencimento', 'orgulho e identidade nacional', 'funciona', NULL, NULL, '30'), ('D12-TR-187-mb', 'O Brasil precisa aparecer menos como símbolo abstrato e mais como experiência vivida.', 'mulheres beneficiárias', 'brasil e pertencimento', 'brasil cotidiano', 'funciona', NULL, NULL, '30'), ('D12-TR-188-mb', 'Brasil Core funciona quando propõe um patriotismo cotidiano, lúcido e afetivo: amar o Brasil sem negar suas falhas, reconhecendo sua potência no povo, na cultura, no SUS, no PIX, na ciência, no esporte, no humor, na família e nas cenas concretas da vida.', 'mulheres beneficiárias', 'brasil e pertencimento', 'orgulho e identidade nacional', 'funciona', NULL, NULL, '31'), ('D12-TR-191-mb', 'As figuras associadas incluem bandeira, cores nacionais, vocabulário de soberania e palavras de ordem patrióticas.', 'mulheres beneficiárias', 'brasil e pertencimento', 'país em disputa', 'funciona', NULL, NULL, '32'), ('D12-TR-194-mb', 'As figuras associadas incluem SUS, PIX, Zé Gotinha, Pilili, cinema nacional, Oscar, ciência brasileira, atletas e Paralimpíadas.', 'mulheres beneficiárias', 'brasil e pertencimento', 'potências do país', 'funciona', NULL, NULL, '32'), ('D12-TR-197-mb', 'As figuras associadas incluem casa, almoço de família, churrasco, risada, meme, estado natal, sotaque, comida, praia e bairro.', 'mulheres beneficiárias', 'brasil e pertencimento', 'brasil cotidiano', 'funciona', NULL, NULL, '32'), ('D12-TR-200-mb', 'As figuras associadas incluem expressões de ressalva seguidas de afirmação de afeto, além de povo brasileiro, comida, energia, lugares bonitos e acolhimento.', 'mulheres beneficiárias', 'brasil e pertencimento', 'orgulho e identidade nacional', 'funciona', NULL, NULL, '32'), ('D12-TR-202-mb', 'A macronarrativa de Brasil Core não deve operar pela fantasia de um país perfeito: sua força está em construir um orgulho lúcido.', 'mulheres beneficiárias', 'brasil e pertencimento', 'orgulho e identidade nacional', 'funciona', NULL, NULL, '32'), ('D12-TR-208-mb', 'A comunicação precisa operar como dispositivo de reencantamento, não pela idealização do país, mas pela reapresentação de suas potências concretas.', 'mulheres beneficiárias', 'brasil e pertencimento', 'potências do país', 'funciona', NULL, NULL, '33'), ('D12-TR-213-mb', 'Dá para amar o Brasil sem fingir que ele é perfeito.', 'mulheres beneficiárias', 'brasil e pertencimento', 'orgulho e identidade nacional', 'funciona', NULL, NULL, '35'), ('D12-TR-215-mb', 'O Brasil ainda dá orgulho quando mostra o que é capaz de fazer.', 'mulheres beneficiárias', 'brasil e pertencimento', 'potências do país', 'funciona', NULL, NULL, '35'), ('D12-TR-217-mb', 'Amar o Brasil também é se reconhecer no lugar de onde se vem.', 'mulheres beneficiárias', 'brasil e pertencimento', 'pertencimento regional', 'funciona', NULL, NULL, '35'), ('D12-TR-219-mb', 'O Brasil não precisa ser perfeito para voltar a parecer possível.', 'mulheres beneficiárias', 'brasil e pertencimento', 'futuro possível', 'funciona', NULL, NULL, '35'), ('D12-TR-223-mb', 'Falar do Brasil concreto, sem idealização: o país que falha, mas também acolhe, emociona e pertence.', 'mulheres beneficiárias', 'brasil e pertencimento', 'brasil cotidiano', 'funciona', NULL, NULL, '36'), ('D12-TR-225-mb', 'A comunicação reconhece falhas e reinscreve o país em experiências afetivas reais.', 'mulheres beneficiárias', 'brasil e pertencimento', 'brasil cotidiano', 'funciona', NULL, NULL, '36'), ('D12-TR-229-mb', 'Usar figuras tangíveis: SUS, PIX, ciência, esporte, cinema, cultura, humor e mascotes nacionais.', 'mulheres beneficiárias', 'brasil e pertencimento', 'potências do país', 'funciona', NULL, NULL, '37'), ('D12-TR-231-mb', 'A comunicação mostra realizações concretas que provam capacidade coletiva.', 'mulheres beneficiárias', 'brasil e pertencimento', 'potências do país', 'funciona', NULL, NULL, '37'), ('D12-TR-235-mb', 'Valorizar regiões, estados, bairros, paisagens, expressões locais e orgulho de origem.', 'mulheres beneficiárias', 'brasil e pertencimento', 'pertencimento regional', 'funciona', NULL, NULL, '38'), ('D12-TR-237-mb', 'A comunicação aproxima o país da identidade regional e da vida local.', 'mulheres beneficiárias', 'brasil e pertencimento', 'pertencimento regional', 'funciona', NULL, NULL, '38'), ('D12-TR-241-mb', 'Combinar realismo e horizonte: reconhecer falhas, mostrar avanços concretos e abrir espaço para futuro.', 'mulheres beneficiárias', 'brasil e pertencimento', 'futuro possível', 'funciona', NULL, NULL, '39'), ('D12-TR-243-mb', 'A comunicação mostra sinais concretos de potência e melhora possível.', 'mulheres beneficiárias', 'brasil e pertencimento', 'potências do país', 'funciona', NULL, NULL, '39'), ('D01-TR-081-mb', '"O Pix é nosso, o SUS pode ser melhor, e o Brasil presta"', 'mulheres beneficiárias', 'brasil e pertencimento', 'orgulho e identidade nacional', 'verbatim', NULL, NULL, '30'), ('D12-TR-201-mb', 'Tem suas falhas, "mas eu amo meu país".', 'mulheres beneficiárias', 'brasil e pertencimento', 'orgulho e identidade nacional', 'verbatim', NULL, NULL, '32'), ('D01-TR-016', 'A tendência histórica de voto deste público não garante adesão: o voto não é certo, é frágil.', 'mulheres beneficiárias', 'participação e voz', 'decisão de voto', 'achado', 'indício', NULL, '13'), ('D01-TR-021', 'A tendência histórica de voto deste público não garante adesão: o voto é frágil.', 'mulheres beneficiárias', 'participação e voz', 'decisão de voto', 'achado', 'indício', NULL, '14'), ('D01-TR-027-mb', 'Há competência real de gestão cotidiana (casa, filhos, negócio e dinheiro), a mesma usada para avaliar quem cumpriu e quem só prometeu; não é preciso ensinar este público a pensar politicamente.', 'mulheres beneficiárias', 'participação e voz', 'decisão de voto', 'achado', 'indício', NULL, '17'), ('D01-TR-033', 'A crítica ao benefício raramente para no valor: recai sobre a pessoa, lida como quem não se esforça, não trabalha ou "tem filho pra ganhar benefício", um julgamento moral constante.', 'mulheres beneficiárias', 'participação e voz', 'bolsa família e transferência de renda', 'achado', 'indício', NULL, '18'), ('D01-TR-090', 'O participação e voz se organiza entre cansaço da política, disputa sobre a voz feminina e busca por reconhecimento da própria decisão.', 'mulheres beneficiárias', 'participação e voz', 'participação política', 'achado', 'indício', NULL, '33'), ('D01-TR-143-mb', 'O Legislativo é pouco compreendido, um grande ponto cego: perguntadas sobre o papel do Senado, as respostas variam entre acerto parcial, confusão com outros cargos e desconhecimento assumido sem constrangimento.', 'mulheres beneficiárias', 'participação e voz', 'funcionamento do legislativo', 'achado', 'indício', NULL, '55'), ('D03-TR-013-mb', 'O WhatsApp é a rede de uso mais universal: 87,3% da população utiliza todos os dias e apenas 7,2% nunca ou quase nunca utiliza.', 'mulheres beneficiárias', 'participação e voz', 'informação e desinformação', 'achado', 'indício', NULL, '20'), ('D03-TR-104-mb', 'Família e fé são apontados como os valores que mais mobilizam o voto.', 'mulheres beneficiárias', 'participação e voz', 'decisão de voto', 'achado', 'indício', NULL, '97'), ('D07-TR-020-mb', 'Os temas de maior impacto são identificados como os preditores do voto, positivos para a situação e negativos para a oposição.', 'mulheres beneficiárias', 'participação e voz', 'comunicação e linguagem', 'achado', 'indício', NULL, '1'), ('D10-TR-012', 'Na macronarrativa de engajamento cívico, a narrativa central vai da representação distante ao protagonismo cotidiano.', 'mulheres beneficiárias', 'participação e voz', 'comunicação e linguagem', 'achado', 'indício', NULL, '8'), ('D10-TR-013', 'O deslocamento semiótico do engajamento cívico é enunciativo: sair do "eles, lá" da política institucional para o "eu, tu, aqui" da experiência vivida, produzindo proximidade, voz e participação.', 'mulheres beneficiárias', 'participação e voz', 'comunicação e linguagem', 'achado', 'indício', NULL, '8'), ('D10-TR-086', 'O voto não é apresentado como troca pelo programa de transferência de renda recebido.', 'mulheres beneficiárias', 'participação e voz', 'decisão de voto', 'achado', 'indício', NULL, '20'), ('D10-TR-087', 'A decisão política é justificada por critérios mais amplos que o benefício: custo de vida, saúde dos filhos, acesso a direitos, segurança e melhora concreta da rotina.', 'mulheres beneficiárias', 'participação e voz', 'custo de vida', 'achado', 'indício', NULL, '20'), ('D10-TR-088', 'Há reconhecimento de avanços e, ao mesmo tempo, forte frustração com promessas que não chegam na ponta.', 'mulheres beneficiárias', 'participação e voz', 'promessa e entrega', 'achado', 'indício', NULL, '20'), ('D10-TR-089', 'Entre indecisas, essa frustração alimenta uma cidadania mais desconfiada, que não rejeita necessariamente a política, mas exige prova de entrega.', 'mulheres beneficiárias', 'participação e voz', 'decisão de voto', 'achado', 'indício', NULL, '20'), ('D10-TR-090', 'Na escuta digital, o engajamento cívico aparece fortemente associado à política institucional, às lideranças nacionais, à polarização e ao sentimento de representação.', 'mulheres beneficiárias', 'participação e voz', 'representação política', 'achado', 'indício', NULL, '20'), ('D10-TR-091', 'Entre os participantes deste estudo, a lógica dominante é menos "eu participo" e mais "alguém me representa".', 'mulheres beneficiárias', 'participação e voz', 'representação política', 'achado', 'indício', NULL, '20'), ('D10-TR-094', 'A polarização gera engajamento.', 'mulheres beneficiárias', 'participação e voz', 'polarização', 'achado', 'indício', NULL, '20'), ('D10-TR-098', 'Essas mulheres já decidem, avaliam, comparam, cobram, compartilham informação e sabem onde a política chega ou falha.', 'mulheres beneficiárias', 'participação e voz', 'participação política', 'achado', 'indício', NULL, '21'), ('D10-TR-102', 'Representação, pertencimento e identificação são isotopias recorrentes: o engajamento se ativa quando há sensação de que alguém fala pela pessoa, a representa ou expressa valores reconhecíveis.', 'mulheres beneficiárias', 'participação e voz', 'representação política', 'achado', 'indício', NULL, '22'), ('D10-TR-103', 'Entre os participantes deste estudo, a política aparece mediada por lideranças, e o sujeito comum tende a figurar mais como apoiador do que como agente da ação política.', 'mulheres beneficiárias', 'participação e voz', 'representação política', 'achado', 'indício', NULL, '22'), ('D10-TR-105', 'Desconfiança, frustração e distância são isotopias recorrentes: o vínculo político é testado pela vida concreta, isto é, preço da comida, saúde dos filhos, acesso a direitos e promessa que não chega.', 'mulheres beneficiárias', 'participação e voz', 'promessa e entrega', 'achado', 'indício', NULL, '22'), ('D10-TR-106', 'A cidadania pragmática e cotidiana estrutura as narrativas: a política se torna relevante quando passa a explicar o que melhora ou piora a vida da família.', 'mulheres beneficiárias', 'participação e voz', 'participação política', 'achado', 'indício', NULL, '22'), ('D10-TR-108', 'Polarização, confronto e defesa de lado são isotopias recorrentes, e a lógica do "eu contra eles" gera intensidade.', 'mulheres beneficiárias', 'participação e voz', 'polarização', 'achado', 'indício', NULL, '22'), ('D10-TR-133', 'O papel atribuído à mulher nesse território é o de intérprete da vida real: ela avalia se a política funciona porque mede seus efeitos na rotina.', 'mulheres beneficiárias', 'participação e voz', 'participação política', 'achado', 'indício', NULL, '26'), ('D10-TR-135', 'A transformação narrativa desse território vai da política percebida como algo distante, feito por outros e em outro lugar, pela via da reconexão com a experiência concreta, até o reconhecimento de que a própria rotina é matéria política e orienta decisões, demandas e escolhas.', 'mulheres beneficiárias', 'participação e voz', 'participação política', 'achado', 'indício', NULL, '26'), ('D10-TR-137', 'O papel atribuído à mulher nesse território é o de guardiã das conquistas da casa: decide pensando no que ajuda a manter os filhos seguros, alimentados, cuidados e com possibilidade de futuro.', 'mulheres beneficiárias', 'participação e voz', 'decisão de voto', 'achado', 'indício', NULL, '27'), ('D10-TR-140', 'O voto é percebido como obrigação, disputa de lados ou julgamento moral sobre quem recebe benefício.', 'mulheres beneficiárias', 'participação e voz', 'estigma do benefício', 'achado', 'indício', NULL, '27'), ('D10-TR-141', 'A transformação narrativa desse território reposiciona o voto como decisão autônoma de quem conhece a realidade, chegando à eleitora que decide por avaliação do que melhora a vida e garante direitos, e não por favor recebido.', 'mulheres beneficiárias', 'participação e voz', 'decisão de voto', 'achado', 'indício', NULL, '27'), ('D10-TR-143', 'O papel atribuído à mulher nesse território é o de fiscal da entrega pública: identifica falhas, compara promessas com realidade, aponta problemas e exige funcionamento.', 'mulheres beneficiárias', 'participação e voz', 'promessa e entrega', 'achado', 'indício', NULL, '28'), ('D10-TR-146', 'A transformação narrativa desse território parte da percepção de que prometem e não cumprem, que alimenta descrença, cansaço e distanciamento, e chega à reclamação convertida em ação cívica, sustentada por linguagem de direito, canal de escuta e expectativa de resposta.', 'mulheres beneficiárias', 'participação e voz', 'promessa e entrega', 'achado', 'indício', NULL, '28'), ('D10-TR-148', 'O papel atribuído à mulher nesse território é o de coautora da representação: sua experiência, sua escolha e sua voz ajudam a sustentar a pauta pública.', 'mulheres beneficiárias', 'participação e voz', 'representação política', 'achado', 'indício', NULL, '29'), ('D10-TR-151', 'A transformação narrativa desse território desloca o vínculo da representação passiva para a participação ativa, até que a mulher se reconheça como parte da construção política e não apenas como público representado ou base de apoio.', 'mulheres beneficiárias', 'participação e voz', 'representação política', 'achado', 'indício', NULL, '29'), ('D10-TR-153', 'O papel atribuído à mulher nesse território é o de parte de uma força coletiva: soma sua voz à de outras mulheres e transforma vivência cotidiana em visibilidade pública.', 'mulheres beneficiárias', 'participação e voz', 'rede de apoio', 'achado', 'indício', NULL, '30'), ('D10-TR-155', 'A transformação narrativa desse território parte de problemas vividos como se fossem individuais, isto é, conta que não fecha, atendimento que falha, filho sem cuidado e direito difícil de acessar, e chega à percepção de pertencer a uma coletividade capaz de dar visibilidade, coragem e pressão por mudança.', 'mulheres beneficiárias', 'participação e voz', 'rede de apoio', 'achado', 'indício', NULL, '30'), ('D11-TR-001', 'O desafio central da comunicação não é ampliar reconhecimento do programa, mas converter cuidado percebido em confiança sustentada.', 'mulheres beneficiárias', 'participação e voz', 'confiança nas instituições', 'achado', 'indício', NULL, '8'), ('D11-TR-140', 'A confiança se forma por confirmação cruzada: aplicativo, TV, jornal, atendimento presencial, conhecidos e mensagens oficiais precisam falar a mesma língua.', 'mulheres beneficiárias', 'participação e voz', 'informação e desinformação', 'achado', 'indício', NULL, '29'), ('D11-TR-157', 'No território de autoestima política e pertencimento, há sentimento de pouca escuta e julgamento, mas também defesa da própria experiência como critério legítimo para avaliar governo.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'achado', 'indício', NULL, '32'), ('D11-TR-158', 'O território de autoestima política e pertencimento tem potencial emergente, especialmente se valorizar a mulher como quem sabe da vida real.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'achado', 'indício', NULL, '32'), ('D11-TR-184', 'A confiança se fortalece quando o governo deixa de ser apenas fonte do benefício e passa a ser percebido como presença contínua: entrega, mantém compromissos, reduz incertezas e melhora condições reais de vida.', 'mulheres beneficiárias', 'participação e voz', 'confiança nas instituições', 'achado', 'indício', NULL, '35'), ('D11-TR-185', 'O benefício é amplamente reconhecido como importante, mas não se traduz automaticamente em confiança política, adesão ou voto.', 'mulheres beneficiárias', 'participação e voz', 'confiança nas instituições', 'achado', 'forte', NULL, '35'), ('D11-TR-186', 'A avaliação sobre governo é construída a partir de um conjunto mais amplo de experiências: melhora percebida na vida, comparação com outros períodos, funcionamento dos serviços, segurança, custo de vida e sensação de cuidado.', 'mulheres beneficiárias', 'participação e voz', 'confiança nas instituições', 'achado', 'indício', NULL, '35'), ('D11-TR-197', 'Entre as beneficiárias a  sensação predominante é de baixa escuta, com percepção de que mulheres como elas não são realmente consideradas pela política.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'achado', 'indício', NULL, '36'), ('D11-TR-199', 'Há uma base potente de autoestima política: quem cuida da casa, dos filhos e das contas sabe avaliar quando a vida melhora ou piora.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'achado', 'forte', NULL, '36'), ('D11-TR-200', 'Essa autoridade cotidiana pode ser ativada como pertencimento: não falar por elas, mas reconhecer que têm critério, experiência e leitura própria.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'achado', 'forte', NULL, '36'), ('D11-TR-206', 'Antes de qualquer comunicação já existe uma narrativa viva: governo bom é aquele que ajuda a mãe a proteger a casa, reduz incerteza e respeita a experiência de quem sabe, no fim do mês, se a vida melhorou ou piorou.', 'mulheres beneficiárias', 'participação e voz', 'confiança nas instituições', 'achado', 'indício', NULL, '37'), ('D11-TR-209', 'O eixo mais promissor é cuidado com previsibilidade, porque organiza os demais temas ao traduzir política pública em segurança cotidiana.', 'mulheres beneficiárias', 'participação e voz', 'confiança nas instituições', 'achado', 'indício', NULL, '38'), ('D11-TR-227', 'Valorizar a voz da beneficiária pode gerar pertencimento, mas precisa de convite mais claro à ação.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'achado', 'indício', NULL, '40'), ('D12-TR-014-2-mb', 'A transformação vai da mulher colocada sob suspeita, acusada de não saber votar ou não entender, para a mulher reconhecida como sujeito político competente, que avalia, compara, decide e sustenta consequências na vida cotidiana.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'achado', 'indício', NULL, NULL), ('D12-TR-098-mb', 'A autoestima política aparece quando a mulher é reconhecida como quem sabe avaliar a própria realidade.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'achado', 'indício', NULL, '20'), ('D12-TR-100', 'Entre CLT, a autoestima política se aproxima mais de direitos, leis e luta coletiva.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'achado', 'indício', NULL, '20'), ('D12-TR-101-mb', 'Há cansaço cívico, desconfiança de promessas e sensação de que políticos aparecem só na eleição.', 'mulheres beneficiárias', 'participação e voz', 'cansaço cívico', 'achado', 'indício', NULL, '20'), ('D12-TR-102-mb', 'O voto é frágil quando não se conecta a efeitos concretos na vida.', 'mulheres beneficiárias', 'participação e voz', 'promessa e entrega', 'achado', 'indício', NULL, '20'), ('D12-TR-104-mb', 'A escuta digital mostra um caminho de empoderamento pelo voto.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'achado', 'indício', NULL, '20'), ('D12-TR-106-mb', 'As redes associam engajamento a representação política e ao debate de gênero.', 'mulheres beneficiárias', 'participação e voz', 'representação política', 'achado', 'indício', NULL, '20'), ('D12-TR-111-mb', 'O engajamento cívico se organiza entre cansaço da política, disputa sobre a voz feminina e busca por reconhecimento da própria decisão.', 'mulheres beneficiárias', 'participação e voz', 'cansaço cívico', 'achado', 'indício', NULL, '21'), ('D12-TR-112-mb', 'Isotopia de distância e cansaço cívico: a política aparece como distante, repetitiva ou oportunista.', 'mulheres beneficiárias', 'participação e voz', 'cansaço cívico', 'achado', 'indício', NULL, '21'), ('D12-TR-113-mb', 'O tema associado é a desconfiança de promessas, a sensação de que políticos aparecem só na eleição e a dificuldade de associar políticas públicas a responsáveis concretos.', 'mulheres beneficiárias', 'participação e voz', 'promessa e entrega', 'achado', 'indício', NULL, '21'), ('D12-TR-115-mb', 'Isotopia de voz sob disputa: a decisão feminina é questionada ou deslegitimada.', 'mulheres beneficiárias', 'participação e voz', 'representação política', 'achado', 'indício', NULL, '21'), ('D12-TR-118-mb', 'Isotopia de decisão cotidiana: a mulher já decide, mas nem sempre reconhece isso como competência política.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'achado', 'indício', NULL, '21'), ('D12-TR-119-mb', 'O tema associado é o voto que ganha sentido ao se conectar à vida real: trabalho, filhos, custo de vida, saúde, segurança, direitos e entregas concretas.', 'mulheres beneficiárias', 'participação e voz', 'promessa e entrega', 'achado', 'indício', NULL, '21'), ('D12-TR-121-mb', 'Isotopia de voz reconhecida: a escolha individual vira participação legítima.', 'mulheres beneficiárias', 'participação e voz', 'participação política', 'achado', 'indício', NULL, '21'), ('D12-TR-126-mb', 'A tensão mais forte está entre decisão deslegitimada e decisão reconhecida.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'achado', 'indício', NULL, '22'), ('D12-TR-127-mb', 'No polo disfórico, a política aparece como distante, polarizada, oportunista ou julgadora, e a mulher é colocada sob suspeita.', 'mulheres beneficiárias', 'participação e voz', 'cansaço cívico', 'achado', 'indício', NULL, '22'), ('D12-TR-128-mb', 'No polo eufórico, o engajamento nasce quando a experiência é reconhecida como competência política.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'achado', 'indício', NULL, '22'), ('D12-TR-129-mb', 'A passagem narrativa vai do "mulher não sabe votar" ao "mulheres decidem todos os dias".', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'achado', 'indício', NULL, '23'), ('D12-TR-134-mb', 'No estado final, há conjunção com voz, legitimidade e autoestima política.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'achado', 'indício', NULL, '23'), ('D12-TR-135-mb', 'O voto não decorre de convencimento de cima para baixo, mas do reconhecimento da própria experiência como critério legítimo de decisão.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'achado', 'indício', NULL, '23'), ('D12-TR-136-mb', 'O ponto de partida é a disjunção com a legitimidade política: voz pouco ouvida, decisão questionada e relação com a política institucional atravessada por desconfiança.', 'mulheres beneficiárias', 'participação e voz', 'representação política', 'achado', 'indício', NULL, '23'), ('D12-TR-137-mb', 'O objeto de valor não é apenas votar ou participar, mas ter a decisão reconhecida como válida.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'achado', 'indício', NULL, '23'), ('D12-TR-138-mb', 'O território "A mulher já decide todos os dias" é transversal e parte da competência cotidiana de escolher, cuidar, comparar, sustentar consequências e resolver problemas concretos.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'achado', 'indício', NULL, '24'), ('D12-TR-140-mb', 'O território "Votar sem ser tutelada" é transversal, ganha força diante dos ataques ao voto feminino e responde à deslegitimação da mulher como sujeito político.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'achado', 'indício', NULL, '24'), ('D12-TR-142-mb', 'O território "Escolher pelo que muda de verdade" é transversal e especialmente potente entre indecisas, organizando o voto como avaliação prática entre promessa, entrega e efeito concreto na vida real.', 'mulheres beneficiárias', 'participação e voz', 'promessa e entrega', 'achado', 'indício', NULL, '24'), ('D12-TR-144-mb', 'O território "Voz coletiva sem cobrança adicional" é mais forte entre mulheres sensíveis à representação e às pautas de gênero, e transforma participação em pertencimento sem convocar a mulher como se estivesse em falta.', 'mulheres beneficiárias', 'participação e voz', 'participação política', 'achado', 'indício', NULL, '24'), ('D12-TR-146-mb', 'Na progressão narrativa dos territórios, o ponto de partida é a competência cotidiana.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'achado', 'indício', NULL, '24'), ('D12-TR-147-mb', 'Na progressão narrativa dos territórios, o segundo passo é a legitimação da escolha política.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'achado', 'indício', NULL, '24'), ('D12-TR-148-mb', 'Na progressão narrativa dos territórios, o terceiro passo é ganhar um critério concreto para avaliar promessas e entregas.', 'mulheres beneficiárias', 'participação e voz', 'promessa e entrega', 'achado', 'indício', NULL, '24'), ('D12-TR-149-mb', 'Na progressão narrativa dos territórios, o ponto de chegada é o pertencimento coletivo, no qual a voz deixa de ser apenas individual e passa a contar politicamente.', 'mulheres beneficiárias', 'participação e voz', 'participação política', 'achado', 'indício', NULL, '24'), ('D12-TR-150-mb', 'A competência política nasce da vida cotidiana: escolher, comparar, cuidar, priorizar e sustentar consequências.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'achado', 'indício', NULL, '25'), ('D12-TR-151-mb', 'A mulher aparece como sujeito competente que já decide sob pressão, mesmo quando não nomeia isso como política.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'achado', 'indício', NULL, '25'), ('D12-TR-153-mb', 'A mulher decide muito, mas não se reconhece como sujeito político.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'achado', 'indício', NULL, '25'), ('D12-TR-155-mb', 'No estado final, há reconhecimento da própria capacidade de decidir politicamente.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'achado', 'indício', NULL, '25'), ('D12-TR-157-mb', 'A mulher aparece como sujeito de escolha, capaz de avaliar sua realidade sem tutela ou desqualificação.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'achado', 'indício', NULL, '26'), ('D12-TR-159-mb', 'A decisão feminina é colocada sob suspeita, com formulações como "não sabe votar" e "não entende".', 'mulheres beneficiárias', 'participação e voz', 'representação política', 'achado', 'indício', NULL, '26'), ('D12-TR-161-mb', 'No estado final, o voto parte de si, com autonomia, respeito e segurança.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'achado', 'indício', NULL, '26'), ('D12-TR-162-mb', 'O voto ganha sentido quando é avaliado por promessa, entrega e impacto concreto no cotidiano.', 'mulheres beneficiárias', 'participação e voz', 'promessa e entrega', 'achado', 'indício', NULL, '27'), ('D12-TR-163-mb', 'A mulher aparece como avaliadora da vida real: compara discurso e resultado pelo que muda no trabalho, nos filhos, no custo de vida e nos direitos.', 'mulheres beneficiárias', 'participação e voz', 'promessa e entrega', 'achado', 'indício', NULL, '27'), ('D12-TR-165-mb', 'A política parece promessa distante ou propaganda eleitoral.', 'mulheres beneficiárias', 'participação e voz', 'cansaço cívico', 'achado', 'indício', NULL, '27'), ('D12-TR-167-mb', 'No estado final, a escolha se torna mais segura porque se apoia em critérios concretos.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'achado', 'indício', NULL, '27'), ('D12-TR-169-mb', 'A mulher aparece como voz que se soma a outras, sem perder sua experiência singular.', 'mulheres beneficiárias', 'participação e voz', 'participação política', 'achado', 'indício', NULL, '28'), ('D12-TR-171-mb', 'A participação parece distante ou surge como mais uma responsabilidade.', 'mulheres beneficiárias', 'participação e voz', 'cansaço cívico', 'achado', 'indício', NULL, '28'), ('D12-TR-173-mb', 'No estado final, participar é percebido como ampliar a própria voz, não como carregar mais peso.', 'mulheres beneficiárias', 'participação e voz', 'participação política', 'achado', 'indício', NULL, '28'), ('D13-TR-191-mb', 'Entre quem tem vínculo formal, a autoestima política está mais amarrada à luta coletiva, como leis trabalhistas e escala de trabalho, com maior desejo de avanço institucional.', 'mulheres beneficiárias', 'participação e voz', 'direitos trabalhistas', 'achado', 'indício', NULL, NULL), ('D13-TR-204-mb', 'Microempreendedoras relatam o antes e depois mais no nível biográfico pessoal, como saída do vínculo formal e maternidade.', 'mulheres beneficiárias', 'participação e voz', 'saúde e sus', 'achado', 'indício', NULL, NULL), ('D13-TR-205-mb', 'Quem tem vínculo formal ancora o antes e depois um pouco mais em políticas públicas e governos específicos.', 'mulheres beneficiárias', 'participação e voz', 'atribuição de políticas públicas', 'achado', 'indício', NULL, NULL), ('D10-TR-093', 'O enquadramento por pertencimento pode aprisionar a conversa na lógica de "nós contra eles".', 'mulheres beneficiárias', 'participação e voz', 'polarização', 'afasta', NULL, NULL, '20'), ('D10-TR-095', 'A polarização aumenta o risco de afastamento, rejeição e leitura de doutrinação.', 'mulheres beneficiárias', 'participação e voz', 'polarização', 'afasta', NULL, NULL, '20'), ('D10-TR-109', 'Essa mesma lógica pode afastar quem rejeita briga, maniqueísmo ou doutrinação.', 'mulheres beneficiárias', 'participação e voz', 'polarização', 'afasta', NULL, NULL, '22'), ('D10-TR-118', 'Os marcadores enunciativos a evitar são eu-ele, lá, então, distanciamento e objetividade.', 'mulheres beneficiárias', 'participação e voz', 'comunicação e linguagem', 'afasta', NULL, NULL, '24'), ('D10-TR-120', 'Tratar a mulher apenas como eleitora, apoiadora ou beneficiária grata enfraquece a comunicação cívica.', 'mulheres beneficiárias', 'participação e voz', 'representação política', 'afasta', NULL, NULL, '25'), ('D10-TR-138', 'Linguagem de favor ou de retribuição enfraquece a comunicação sobre o voto.', 'mulheres beneficiárias', 'participação e voz', 'decisão de voto', 'afasta', NULL, NULL, '27'), ('D10-TR-150', 'O pertencimento deve ser valorizado sem reduzir a mulher à gratidão por uma liderança.', 'mulheres beneficiárias', 'participação e voz', 'representação política', 'afasta', NULL, NULL, '29'), ('D11-TR-010', 'Tom celebratório, promessa absoluta e cobrança de gratidão afastam.', 'mulheres beneficiárias', 'participação e voz', 'comunicação de serviço', 'afasta', NULL, NULL, '8'), ('D11-TR-050', 'A comunicação precisa sustentar simultaneamente reconhecimento e dificuldade, porque tom excessivamente celebratório gera rejeição ao ignorar que a melhora, quando existe, ainda é frágil e incompleta.', 'mulheres beneficiárias', 'participação e voz', 'comunicação de serviço', 'afasta', NULL, NULL, '15'), ('D11-TR-189', 'Narrativas que sugerem gratidão, favor ou troca entre benefício e voto tendem a perder legitimidade.', 'mulheres beneficiárias', 'participação e voz', 'confiança nas instituições', 'afasta', NULL, NULL, '35'), ('D11-TR-211', 'Política e voto exigem mais cautela: a confiança pode ser fortalecida, mas a comunicação não deve parecer cobrança de gratidão.', 'mulheres beneficiárias', 'participação e voz', 'confiança nas instituições', 'afasta', NULL, NULL, '38'), ('D11-TR-261', 'O termo política pública pode parecer técnico ou distante se não vier acompanhado de benefício, despesa ou situação real.', 'mulheres beneficiárias', 'participação e voz', 'comunicação de serviço', 'afasta', NULL, NULL, '43'), ('D11-TR-286', 'Sem solução visível, a mensagem sobre responsabilidades tende a aumentar frustração.', 'mulheres beneficiárias', 'participação e voz', 'acesso a benefícios e atendimento', 'afasta', NULL, NULL, '45'), ('D11-TR-313', 'O reconhecimento é positivo, mas sozinho pode ficar no campo da autoestima sem produzir ação.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'afasta', NULL, NULL, '48'), ('D12-TR-004-mb', 'Promessas que não encostam na rotina geram desconfiança.', 'mulheres beneficiárias', 'participação e voz', 'promessa e entrega', 'afasta', NULL, NULL, '7'), ('D12-TR-097-mb', 'O engajamento fracassa quando soa como obrigação, tom de cima para baixo ou cobrança adicional.', 'mulheres beneficiárias', 'participação e voz', 'cansaço cívico', 'afasta', NULL, NULL, '20'), ('D12-TR-107-mb', 'Circulam conteúdos que afastam mulheres do debate ao tratá-las como "burras" ou como estando fora dele.', 'mulheres beneficiárias', 'participação e voz', 'representação política', 'afasta', NULL, NULL, '20'), ('D12-TR-116-mb', 'O tema associado são discursos que afastam mulheres da política, ridicularizam seu voto ou colocam sua capacidade de decisão sob suspeita.', 'mulheres beneficiárias', 'participação e voz', 'representação política', 'afasta', NULL, NULL, '21'), ('D12-TR-168-mb', 'Participar não pode soar como mais uma obrigação para quem já carrega demais.', 'mulheres beneficiárias', 'participação e voz', 'participação política', 'afasta', NULL, NULL, '28'), ('D01-TR-001-mb', 'Cerca de 4 milhões de eleitores permanecem indecisos para 2026.', 'mulheres beneficiárias', 'participação e voz', 'decisão de voto', 'contexto', NULL, NULL, '6'), ('D01-TR-004-mb', 'Entre os votos em aberto, 53% correspondem a mulheres, 32% a jovens de 16 a 34 anos e 23% a pessoas 60+.', 'mulheres beneficiárias', 'participação e voz', 'decisão de voto', 'contexto', NULL, NULL, '8'), ('D01-TR-007-mb', '81% dos eleitores do estado de São Paulo não têm escolha definida para o Senado.', 'mulheres beneficiárias', 'participação e voz', 'decisão de voto', 'contexto', NULL, NULL, '8'), ('D01-TR-012-mb', 'Mulheres representam 52,84% do eleitorado, mais de 83,8 milhões de eleitoras.', 'mulheres beneficiárias', 'participação e voz', 'decisão de voto', 'contexto', NULL, NULL, '13'), ('D01-TR-015-mb', 'O voto feminino costuma ser decidido nas semanas finais da campanha, com avaliação por critérios práticos de estabilidade familiar e considerando toda a comunidade, não apenas a própria pessoa.', 'mulheres beneficiárias', 'participação e voz', 'decisão de voto', 'contexto', NULL, NULL, '13'), ('D01-TR-101-mb', 'O eleitorado de 16 a 18 anos encolheu 14,5% desde 2022, justamente o grupo que deveria estar entrando no jogo eleitoral.', 'mulheres beneficiárias', 'participação e voz', 'decisão de voto', 'contexto', NULL, NULL, '37'), ('D11-TR-097', 'As narrativas devem valorizar a beneficiária como alguém ativa, que usa o benefício para proteger a família, e não como dependente ou passiva diante do Estado.', 'mulheres beneficiárias', 'participação e voz', 'estigma do benefício', 'contexto', NULL, NULL, '23'), ('D11-TR-155', 'No território de política, confiança e voto, a política é atravessada por cansaço, comparação, memória e desconfiança, e o benefício importa mas não basta sozinho.', 'mulheres beneficiárias', 'participação e voz', 'confiança nas instituições', 'contexto', NULL, NULL, '32'), ('D11-TR-212', 'Autoestima política é uma oportunidade: transformar beneficiárias em mulheres reconhecidas pela capacidade de avaliar, decidir e cobrar.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'contexto', NULL, NULL, '38'), ('D12-TR-016-mb', 'A mulher já decide todos os dias é um dos territórios de comunicação do engajamento cívico.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'contexto', NULL, NULL, '8'), ('D12-TR-124-mb', 'O ponto mais disfórico da macronarrativa é a distância e o cansaço cívico; o ponto mais eufórico é a voz reconhecida.', 'mulheres beneficiárias', 'participação e voz', 'cansaço cívico', 'contexto', NULL, NULL, '21'), ('D01-TR-043', 'Para beneficiárias, os estigmas são sentidos diariamente; tratar a beneficiária como gestora, não como suspeita, desarma a disputa moral sobre dependência quando a comunicação mostra a mulher explicando o peso de cada escolha.', 'mulheres beneficiárias', 'participação e voz', 'bolsa família e transferência de renda', 'funciona', NULL, NULL, '21'), ('D01-TR-094', 'Preservar a autonomia do voto, nunca o oferecer como retribuição: falar em "retribuição" fecha a conversa; falar em proteger conquistas e o que não pode voltar a faltar, sim.', 'mulheres beneficiárias', 'participação e voz', 'decisão de voto', 'funciona', NULL, NULL, '35'), ('D01-TR-096', 'Tratar a mulher como coautora, não como base de apoio: sair do "ele fez por você" para "isso também é conquista de quem vive e cobra".', 'mulheres beneficiárias', 'participação e voz', 'participação política', 'funciona', NULL, NULL, '35'), ('D01-TR-144-mb', 'Quando a pergunta sobre o Senado é reformulada de forma concreta, associando-o a salário, escala de trabalho e direitos, o tom muda de indiferença para indignação.', 'mulheres beneficiárias', 'participação e voz', 'funcionamento do legislativo', 'funciona', NULL, NULL, '55'), ('D01-TR-147-mb', 'A comunicação sobre o Legislativo não precisa começar pelo Senado, precisa começar pelo problema: escala 6x1, salário, transporte, segurança e segurança digital.', 'mulheres beneficiárias', 'participação e voz', 'funcionamento do legislativo', 'funciona', NULL, NULL, '55'), ('D10-TR-014', 'A política só se aproxima quando deixa de ser "eles lá" e passa a ser "eu, tu, aqui": rotina, direitos, escolha, cobrança e participação.', 'mulheres beneficiárias', 'participação e voz', 'participação política', 'funciona', NULL, NULL, '8'), ('D10-TR-084', 'A política só se aproxima quando deixa de ser disputa entre líderes e passa a ser possibilidade concreta de melhorar a vida.', 'mulheres beneficiárias', 'participação e voz', 'participação política', 'funciona', NULL, NULL, '20'), ('D10-TR-085', 'A oportunidade narrativa está em reposicionar o engajamento cívico como competência cotidiana dessas mulheres.', 'mulheres beneficiárias', 'participação e voz', 'participação política', 'funciona', NULL, NULL, '20'), ('D10-TR-092', 'Pertencimento e identificação mobilizam a conversa cívica.', 'mulheres beneficiárias', 'participação e voz', 'representação política', 'funciona', NULL, NULL, '20'), ('D10-TR-096', 'A comunicação precisa deslocar o engajamento do campo da torcida política para o campo da experiência vivida: participar, votar, cobrar e opinar devem aparecer como formas de defender direitos e melhorar a vida real.', 'mulheres beneficiárias', 'participação e voz', 'participação política', 'funciona', NULL, NULL, '20'), ('D10-TR-097', 'Um território promissor é transformar representação em protagonismo: não apenas "alguém fala por você", mas "sua experiência conta, sua escolha pesa, sua voz ajuda a garantir direitos e abrir futuro".', 'mulheres beneficiárias', 'participação e voz', 'representação política', 'funciona', NULL, NULL, '20'), ('D10-TR-099', 'A comunicação deve reconhecer essa autoridade sem cair em convocação eleitoral direta.', 'mulheres beneficiárias', 'participação e voz', 'decisão de voto', 'funciona', NULL, NULL, '21'), ('D10-TR-100', 'O foco não é pedir adesão, mas mostrar que a participação pode ser ferramenta para proteger conquistas, exigir funcionamento e transformar experiência de vida em força coletiva.', 'mulheres beneficiárias', 'participação e voz', 'participação política', 'funciona', NULL, NULL, '21'), ('D10-TR-101', 'A política só se aproxima quando toca o cotidiano e ajuda a proteger direitos concretos.', 'mulheres beneficiárias', 'participação e voz', 'participação política', 'funciona', NULL, NULL, '22'), ('D10-TR-104', 'Presidente, voto, eleição, partido, Congresso, STF, democracia, país, povo e a expressão "meu presidente" são as figuras que organizam a política como pertencimento simbólico e disputa de posição.', 'mulheres beneficiárias', 'participação e voz', 'comunicação e linguagem', 'funciona', NULL, NULL, '22'), ('D10-TR-107', 'Mercado, comida cara, remédio, terapia, benefício, escola, saúde, filhos, CRAS e atendimento são as figuras que traduzem o voto e a confiança política em experiência vivida.', 'mulheres beneficiárias', 'participação e voz', 'participação política', 'funciona', NULL, NULL, '22'), ('D10-TR-110', 'A participação deve ser tematizada como proteção de direitos, mobilizando sem recair apenas no "nós contra eles".', 'mulheres beneficiárias', 'participação e voz', 'polarização', 'funciona', NULL, NULL, '22'), ('D10-TR-111', 'Direitos, políticas públicas, consulta, denúncia, cobrança, comunidade, rede de mulheres e voz são as figuras que materializam uma participação menos passiva e mais conectada ao protagonismo cotidiano.', 'mulheres beneficiárias', 'participação e voz', 'participação política', 'funciona', NULL, NULL, '22'), ('D10-TR-112', 'A oportunidade é transformar representação em protagonismo, saindo de "alguém me representa" para "minha experiência também constrói a política".', 'mulheres beneficiárias', 'participação e voz', 'representação política', 'funciona', NULL, NULL, '23'), ('D10-TR-113', 'A comunicação deve reposicionar a mulher como sujeito da narrativa, e não apenas como destinatária de uma liderança que age em seu nome.', 'mulheres beneficiárias', 'participação e voz', 'representação política', 'funciona', NULL, NULL, '24'), ('D10-TR-114', 'As políticas públicas, o voto, a informação e os canais de participação funcionam como competências que ampliam o poder fazer dessa mulher, dotando-a de habilidade e conhecimento para cobrar, decidir, avaliar, proteger conquistas e reivindicar mudanças.', 'mulheres beneficiárias', 'participação e voz', 'participação política', 'funciona', NULL, NULL, '24'), ('D10-TR-115', 'O deslocamento discursivo é fundamental: sair de uma política enunciada no "lá", por "eles", sobre grandes disputas, e construir uma política no "aqui", dirigida a "você", a partir da experiência concreta.', 'mulheres beneficiárias', 'participação e voz', 'participação política', 'funciona', NULL, NULL, '24'), ('D10-TR-116', 'O efeito de sentido buscado é a proximidade: além de se sentir representada, a mulher se reconhece como parte ativa da vida pública.', 'mulheres beneficiárias', 'participação e voz', 'participação política', 'funciona', NULL, NULL, '24'), ('D10-TR-117', 'Os marcadores enunciativos recomendados são eu-tu, aqui, agora, aproximação e subjetividade.', 'mulheres beneficiárias', 'participação e voz', 'comunicação e linguagem', 'funciona', NULL, NULL, '24'), ('D10-TR-119', 'O ponto comum dos territórios é deslocar o engajamento cívico da lógica passiva da representação para uma narrativa de protagonismo cotidiano.', 'mulheres beneficiárias', 'participação e voz', 'representação política', 'funciona', NULL, NULL, '25'), ('D10-TR-121', 'O caminho mais forte é apresentá-la como sujeito que sabe avaliar a vida real, decide com base no que afeta sua família, cobra funcionamento e transforma rotina em participação.', 'mulheres beneficiárias', 'participação e voz', 'participação política', 'funciona', NULL, NULL, '25'), ('D10-TR-122', 'O território "minha rotina também é política" se organiza pela passagem da política como disputa distante para a política lida no mercado, na saúde dos filhos, no benefício, na escola e no atendimento.', 'mulheres beneficiárias', 'participação e voz', 'participação política', 'funciona', NULL, NULL, '25'), ('D10-TR-123', 'A promessa comunicacional desse território é que a experiência vivida todos os dias mostra o que precisa mudar e ajuda a construir o caminho.', 'mulheres beneficiárias', 'participação e voz', 'participação política', 'funciona', NULL, NULL, '25'), ('D10-TR-124', 'O território "votar é proteger o que importa" se organiza pelo sentido do voto como defesa de direitos, serviços e condições concretas para a família viver melhor.', 'mulheres beneficiárias', 'participação e voz', 'decisão de voto', 'funciona', NULL, NULL, '25'), ('D10-TR-125', 'A promessa comunicacional desse território é que a escolha da eleitora ajuda a proteger conquistas e abrir futuro para ela e para os filhos.', 'mulheres beneficiárias', 'participação e voz', 'decisão de voto', 'funciona', NULL, NULL, '25'), ('D10-TR-126', 'O território "da voz que reclama à voz que cobra" se organiza pela conversão da frustração com promessas não cumpridas em cobrança legítima, desde que existam canal, escuta e consequência.', 'mulheres beneficiárias', 'participação e voz', 'promessa e entrega', 'funciona', NULL, NULL, '25'), ('D10-TR-127', 'A promessa comunicacional desse território é que a voz tem força quando aponta o problema, exige resposta e ajuda a fazer a política funcionar.', 'mulheres beneficiárias', 'participação e voz', 'promessa e entrega', 'funciona', NULL, NULL, '25'), ('D10-TR-128', 'O território "representação com participação" se organiza pelo reconhecimento de que a identificação com lideranças mobiliza, mas precisa evoluir para protagonismo coletivo e apropriação das conquistas.', 'mulheres beneficiárias', 'participação e voz', 'representação política', 'funciona', NULL, NULL, '25'), ('D10-TR-129', 'A promessa comunicacional desse território é que não basta alguém falar pela mulher: ela também ocupa lugar na conversa sobre seus direitos.', 'mulheres beneficiárias', 'participação e voz', 'representação política', 'funciona', NULL, NULL, '25'), ('D10-TR-130', 'O território "coletividade que dá coragem" se organiza pela percepção de que a experiência individual não é isolada e pode se somar à de outras mulheres.', 'mulheres beneficiárias', 'participação e voz', 'rede de apoio', 'funciona', NULL, NULL, '25'), ('D10-TR-131', 'A promessa comunicacional desse território é que, quando muitas mulheres contam, cobram e participam, a realidade ganha visibilidade e força de mudança.', 'mulheres beneficiárias', 'participação e voz', 'rede de apoio', 'funciona', NULL, NULL, '25'), ('D10-TR-132', 'A política deixa de ser disputa distante quando é traduzida nas experiências que organizam a rotina: comida cara, saúde dos filhos, escola, benefício, transporte, atendimento e contas do mês.', 'mulheres beneficiárias', 'participação e voz', 'custo de vida', 'funciona', NULL, NULL, '26'), ('D10-TR-134', 'A comunicação deve usar situações concretas como ponto de entrada, mostrando que falar de política também é falar do preço da comida, da consulta que demora, do benefício que organiza o mês e da escola que precisa funcionar.', 'mulheres beneficiárias', 'participação e voz', 'custo de vida', 'funciona', NULL, NULL, '26'), ('D10-TR-136', 'O voto não deve ser tratado como gratidão pelo benefício, mas como forma de proteger direitos e condições concretas de vida para a família.', 'mulheres beneficiárias', 'participação e voz', 'decisão de voto', 'funciona', NULL, NULL, '27'), ('D10-TR-139', 'Recomenda-se falar de escolha, proteção, continuidade, direitos e futuro, com formulações sobre o que precisa continuar, o que precisa melhorar e o que não pode voltar a faltar.', 'mulheres beneficiárias', 'participação e voz', 'decisão de voto', 'funciona', NULL, NULL, '27'), ('D10-TR-142', 'A decepção com promessas não cumpridas pode se transformar em cobrança legítima quando há orientação, canal e possibilidade de resposta.', 'mulheres beneficiárias', 'participação e voz', 'promessa e entrega', 'funciona', NULL, NULL, '28'), ('D10-TR-144', 'A comunicação deve validar a reclamação como forma de participação.', 'mulheres beneficiárias', 'participação e voz', 'participação política', 'funciona', NULL, NULL, '28'), ('D10-TR-145', 'A comunicação deve mostrar caminhos práticos para cobrar: onde falar, como registrar, quem procurar, como acompanhar e por que a cobrança importa.', 'mulheres beneficiárias', 'participação e voz', 'acesso a benefícios e atendimento', 'funciona', NULL, NULL, '28'), ('D10-TR-147', 'A identificação com lideranças mobiliza, mas o engajamento se torna mais forte quando fica claro que direitos e conquistas também dependem de participação coletiva.', 'mulheres beneficiárias', 'participação e voz', 'representação política', 'funciona', NULL, NULL, '29'), ('D10-TR-149', 'A comunicação deve sair da fórmula de que uma liderança fez algo pela pessoa e ir para a conquista de quem vive, defende e cobra.', 'mulheres beneficiárias', 'participação e voz', 'representação política', 'funciona', NULL, NULL, '29'), ('D10-TR-152', 'O engajamento cresce quando fica claro que a dificuldade vivida não é falha individual, mas experiência compartilhada por outras mulheres que também cuidam, cobram e buscam direitos.', 'mulheres beneficiárias', 'participação e voz', 'rede de apoio', 'funciona', NULL, NULL, '30'), ('D10-TR-154', 'A comunicação deve usar linguagem de rede, comunidade e escuta, com formulações como "você não está sozinha", "outras mães também passam por isso" e "quando muitas falam, a realidade aparece".', 'mulheres beneficiárias', 'participação e voz', 'rede de apoio', 'funciona', NULL, NULL, '30'), ('D11-TR-020', 'A comunicação mais eficaz começa pela vida concreta e demonstra entender a régua real da rotina antes de falar de governo, voto ou grandes indicadores.', 'mulheres beneficiárias', 'participação e voz', 'comunicação de serviço', 'funciona', NULL, NULL, '11'), ('D11-TR-135', 'Explicar quem paga, quem atende e quem resolve é necessário, mas só funciona se ficar claro o que fazer quando o atendimento falha.', 'mulheres beneficiárias', 'participação e voz', 'comunicação de serviço', 'funciona', NULL, NULL, '28'), ('D11-TR-156', 'O território de política, confiança e voto tem potencial condicionado: precisa provar cuidado sem parecer uso eleitoral.', 'mulheres beneficiárias', 'participação e voz', 'confiança nas instituições', 'funciona', NULL, NULL, '32'), ('D11-TR-160', 'O caminho mais promissor não é falar de governo em abstrato, mas mostrar como cuidado, família, dignidade e confiança aparecem na rotina de quem sustenta a casa.', 'mulheres beneficiárias', 'participação e voz', 'comunicação de serviço', 'funciona', NULL, NULL, '32'), ('D11-TR-190', 'A ação pública é valorizada quando aparece como dever do governo, não como concessão pessoal.', 'mulheres beneficiárias', 'participação e voz', 'confiança nas instituições', 'funciona', NULL, NULL, '35'), ('D11-TR-191', 'O caminho mais seguro não é pedir reconhecimento direto, mas acumular prova de cuidado: mostrar o que funciona, o que melhorou, quem fez e como isso protege a vida cotidiana.', 'mulheres beneficiárias', 'participação e voz', 'comunicação de serviço', 'funciona', NULL, NULL, '35'), ('D11-TR-196', 'É importante reconhecer a beneficiária como sujeito de avaliação, não como alvo de convencimento, porque ela mede a política no orçamento, no filho e na rotina.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'funciona', NULL, NULL, '36'), ('D11-TR-207', 'A macronarrativa mais forte nasce da vida concreta.', 'mulheres beneficiárias', 'participação e voz', 'comunicação de serviço', 'funciona', NULL, NULL, '38'), ('D11-TR-245', 'A linguagem simples e próxima funciona porque não exige repertório político ou institucional para ser compreendida.', 'mulheres beneficiárias', 'participação e voz', 'comunicação de serviço', 'funciona', NULL, NULL, '42'), ('D11-TR-314', 'Transformar reconhecimento em convite: contar a própria experiência, tirar dúvida, compartilhar com outra mãe e cobrar o próprio direito.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'funciona', NULL, NULL, '48'), ('D11-TR-315', 'Conectar autoestima política a situações concretas: orçamento da casa, filhos, benefício, atendimento, cadastro e acesso a serviços.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'funciona', NULL, NULL, '48'), ('D11-TR-322', 'Falar menos de política em abstrato e mais de situações concretas: o que chega, onde acessar, como manter e como resolver.', 'mulheres beneficiárias', 'participação e voz', 'comunicação de serviço', 'funciona', NULL, NULL, '50'), ('D11-TR-327', 'O tom deve reconhecer essas mulheres como mães, gestoras da casa e avaliadoras legítimas da própria realidade.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'funciona', NULL, NULL, '51'), ('D12-TR-015-mb', 'O engajamento precisa sair da cobrança e virar reconhecimento: tratar o voto como extensão da experiência prática, com informação clara, promessa verificável, escuta, respeito e consequência concreta na rotina.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'funciona', NULL, NULL, '8'), ('D12-TR-095-mb', 'O engajamento só ganha força quando sai da cobrança política e reconhece a mulher como sujeito capaz de decidir a partir da própria vida.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'funciona', NULL, NULL, '20'), ('D12-TR-096-mb', 'O engajamento funciona quando fala de escolha e de reconhecimento da experiência.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'funciona', NULL, NULL, '20'), ('D12-TR-108-mb', 'A macronarrativa precisa deslocar o engajamento do campo da disputa política para o campo da competência cotidiana de decidir.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'funciona', NULL, NULL, '20'), ('D12-TR-109-mb', 'A comunicação deve afirmar a mulher como sujeito competente: ela decide todos os dias e também pode decidir politicamente, sem ser tutelada, ridicularizada ou deslegitimada.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'funciona', NULL, NULL, '20'), ('D12-TR-110-mb', 'O caminho não é convocar mais responsabilidade, mas tornar o engajamento mais próximo, verificável e menos punitivo, com escolha, escuta, consequência concreta e respeito à inteligência política.', 'mulheres beneficiárias', 'participação e voz', 'participação política', 'funciona', NULL, NULL, '20'), ('D12-TR-114-mb', 'As figuras associadas incluem eleição, campanha, promessa, político, governo, Senado, Brasília e a expressão "só aparece na eleição".', 'mulheres beneficiárias', 'participação e voz', 'cansaço cívico', 'funciona', NULL, NULL, '21'), ('D12-TR-117-mb', 'As figuras associadas incluem "mulher não sabe votar", "mulher não deveria votar", ataques, polarização e misoginia.', 'mulheres beneficiárias', 'participação e voz', 'representação política', 'funciona', NULL, NULL, '21'), ('D12-TR-120-mb', 'As figuras associadas incluem casa, mercado, escola, creche, trabalho, remédio, salário, escala 6x1, benefício e a comparação entre promessa e entrega.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'funciona', NULL, NULL, '21'), ('D12-TR-122-mb', 'O tema associado é o engajamento que funciona ao reconhecer a experiência, a inteligência prática e a capacidade de avaliar a vida real.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'funciona', NULL, NULL, '21'), ('D12-TR-123-mb', 'As figuras associadas incluem "nós, mulheres, decidimos", voto, escuta, participação, representação e o uso de "a gente".', 'mulheres beneficiárias', 'participação e voz', 'participação política', 'funciona', NULL, NULL, '21'), ('D12-TR-125-mb', 'Não se deve partir da oposição simples entre mulher engajada e desengajada.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'funciona', NULL, NULL, '22'), ('D12-TR-130-mb', 'A comunicação precisa deslocar o engajamento cívico do regime da cobrança para o regime do reconhecimento.', 'mulheres beneficiárias', 'participação e voz', 'comunicação e linguagem', 'funciona', NULL, NULL, '23'), ('D12-TR-131-mb', 'Não convocar a mulher a participar como se estivesse em falta, e sim mostrar que ela já exerce competência política quando avalia, compara, cuida, decide e sustenta consequências na vida cotidiana.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'funciona', NULL, NULL, '23'), ('D12-TR-132-mb', 'A transformação acontece quando o voto é apresentado como extensão de uma competência já existente: decidir diante da escassez, comparar promessa e entrega, avaliar efeitos concretos e proteger o que importa.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'funciona', NULL, NULL, '23'), ('D12-TR-133-mb', 'Políticas públicas, informação clara, representação e prova concreta funcionam como adjuvantes para ampliar o poder de escolha.', 'mulheres beneficiárias', 'participação e voz', 'atribuição de políticas públicas', 'funciona', NULL, NULL, '23'), ('D12-TR-139-mb', 'Quem decide tanta coisa na vida também sabe decidir politicamente.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'funciona', NULL, NULL, '24'), ('D12-TR-141-mb', 'O voto da mulher não precisa de tutela: precisa de respeito, informação e reconhecimento.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'funciona', NULL, NULL, '24'), ('D12-TR-143-mb', 'Escolher é comparar promessa, entrega e efeito concreto no dia a dia.', 'mulheres beneficiárias', 'participação e voz', 'promessa e entrega', 'funciona', NULL, NULL, '24'), ('D12-TR-145-mb', 'Participar não é carregar mais uma responsabilidade: é fazer a própria voz contar.', 'mulheres beneficiárias', 'participação e voz', 'participação política', 'funciona', NULL, NULL, '24'), ('D12-TR-152-mb', 'Mostrar decisões reais da rotina e conectá-las ao voto sem tom professoral ou convocação moral.', 'mulheres beneficiárias', 'participação e voz', 'comunicação e linguagem', 'funciona', NULL, NULL, '25'), ('D12-TR-154-mb', 'A comunicação revela que a experiência cotidiana também é critério político.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'funciona', NULL, NULL, '25'), ('D12-TR-156-mb', 'O voto feminino precisa ser tratado como decisão legítima, não como escolha a ser corrigida, ensinada ou controlada.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'funciona', NULL, NULL, '26'), ('D12-TR-158-mb', 'Responder à deslegitimação com respeito, informação clara e reconhecimento da inteligência prática.', 'mulheres beneficiárias', 'participação e voz', 'representação política', 'funciona', NULL, NULL, '26'), ('D12-TR-160-mb', 'A comunicação legitima a voz e a capacidade de julgamento.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'funciona', NULL, NULL, '26'), ('D12-TR-164-mb', 'Usar provas concretas, exemplos próximos e linguagem de consequência: o que prometeu, o que entregou, o que mudou.', 'mulheres beneficiárias', 'participação e voz', 'promessa e entrega', 'funciona', NULL, NULL, '27'), ('D12-TR-166-mb', 'A comunicação aproxima o voto de efeitos verificáveis na rotina.', 'mulheres beneficiárias', 'participação e voz', 'promessa e entrega', 'funciona', NULL, NULL, '27'), ('D12-TR-170-mb', 'Falar em pertencimento, escuta e força coletiva, sem transformar participação em cobrança.', 'mulheres beneficiárias', 'participação e voz', 'participação política', 'funciona', NULL, NULL, '28'), ('D12-TR-172-mb', 'A comunicação mostra que a própria voz pode contar junto com a de outras mulheres.', 'mulheres beneficiárias', 'participação e voz', 'participação política', 'funciona', NULL, NULL, '28'), ('D12-TR-252-mb', 'Legitimar a leitura da realidade: a comunicação deve partir do que a mulher já sabe avaliar, como o mês que fecha ou não fecha, o tempo que falta, a promessa que não chega e o serviço que funciona ou falha.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'funciona', NULL, NULL, '42'), ('D01-TR-089', '"O voto é frágil, não ignorante."', 'mulheres beneficiárias', 'participação e voz', 'decisão de voto', 'verbatim', NULL, NULL, '33'), ('D11-TR-182', '"Quem está lá em cima nem sempre sabe o que a gente passa aqui embaixo."', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'verbatim', NULL, NULL, '34'), ('D11-TR-192', 'Eu acho que a gente se sente mais segura quando eles nos passam a segurança de prometer e cumprir. [...] Ele prometeu que o benefício tal iria ser liberado, ele cumprir.', 'mulheres beneficiárias', 'participação e voz', 'confiança nas instituições', 'verbatim', NULL, NULL, '35'), ('D11-TR-194', 'Ninguém está mais ligando para o povo. Está ligando para ganhar. [...] A gente está aqui de plateia.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'verbatim', NULL, NULL, '35'), ('D11-TR-203', 'Quem sabe da minha necessidade sou eu. Quem está dentro da minha casa sou eu.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'verbatim', NULL, NULL, '36'), ('D11-TR-204', 'A gente vê na prática. É a gente que sabe se o dinheiro está dando ou não está dando.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'verbatim', NULL, NULL, '36'), ('D11-TR-205', 'Eles falam muita coisa, mas quem sente mesmo somos nós.', 'mulheres beneficiárias', 'participação e voz', 'competência e autoestima política', 'verbatim', NULL, NULL, '36'), ('D10-TR-001', 'As três macronarrativas analisadas operam a mesma virada semiótica: a mulher deixa de ser apenas destinatária da política pública e passa a sujeito competente da transformação.', 'mulheres beneficiárias', NULL, 'comunicação e linguagem', 'perfil', NULL, NULL, '7'), ('D10-TR-002', 'A política pública deve ocupar a posição narrativa de adjuvante, apoiando a ação da mulher em vez de figurar como agente principal da transformação.', 'mulheres beneficiárias', NULL, 'atribuição de políticas públicas', 'perfil', NULL, NULL, '7'), ('D10-TR-003', 'A ampliação do poder fazer atribuído a essa mulher se expressa em seis capacidades: proteger, decidir, organizar, cobrar, participar e planejar.', 'mulheres beneficiárias', NULL, 'participação política', 'perfil', NULL, NULL, '7'), ('D11-TR-002', 'Entre os participantes deste estudo, a rotina é uma gestão permanente de escassez que envolve dinheiro, tempo, apoio, segurança e energia emocional.', 'mulheres beneficiárias', NULL, 'cuidado e sobrecarga', 'perfil', NULL, NULL, '8'), ('D11-TR-008', 'As narrativas mais fortes partem da vida concreta: benefício que chega, regra clara, atendimento que resolve, família protegida e mãe reconhecida como quem sabe avaliar a própria realidade.', 'mulheres beneficiárias', NULL, 'comunicação de serviço', 'perfil', NULL, NULL, '8'), ('D11-TR-013', 'A gestão de escassez não se limita a dinheiro: alcança também tempo, energia, apoio e segurança.', 'mulheres beneficiárias', NULL, 'cuidado e sobrecarga', 'perfil', NULL, NULL, '11'), ('D11-TR-015', 'A maternidade aparece como eixo organizador da vida prática, misturando casa, trabalho, escola, saúde, alimentação e proteção dos filhos numa mesma carga mental.', 'mulheres beneficiárias', NULL, 'cuidado e sobrecarga', 'perfil', NULL, NULL, '11'), ('D11-TR-024', 'A vida cotidiana não é apenas corrida: é sustentada por uma capacidade constante de administrar simultaneidades entre trabalho, filhos, casa, escola, alimentação, limpeza, atendimento a clientes e cuidado com familiares.', 'mulheres beneficiárias', NULL, 'cuidado e sobrecarga', 'perfil', NULL, NULL, '12'), ('D11-TR-026', 'A falta de rede de apoio transforma qualquer imprevisto em crise de organização.', 'mulheres beneficiárias', NULL, 'rede de apoio', 'perfil', NULL, NULL, '12'), ('D11-TR-028', 'A maternidade é vivida como responsabilidade principal mesmo quando há companheiro ou família por perto, o que cria uma régua específica de avaliação: uma política só é percebida como útil quando facilita a vida de quem cuida.', 'mulheres beneficiárias', NULL, 'cuidado e sobrecarga', 'perfil', NULL, NULL, '12'), ('D11-TR-029', 'O cansaço relatado não é apenas físico, mas mental, porque envolve antecipar problemas, calcular dinheiro, organizar horários, proteger os filhos e manter a casa funcionando.', 'mulheres beneficiárias', NULL, 'cuidado e sobrecarga', 'perfil', NULL, NULL, '12'), ('D11-TR-092', 'O benefício é defendido como direito, mas ainda carrega estigma, e a beneficiária não quer ser lida como acomodada.', 'mulheres beneficiárias', NULL, 'estigma do benefício', 'perfil', NULL, NULL, '23'), ('D11-TR-095', 'O estigma desloca a conversa do direito para o julgamento moral da mulher pobre, especialmente da mãe beneficiária.', 'mulheres beneficiárias', NULL, 'estigma do benefício', 'perfil', NULL, NULL, '23'), ('D11-TR-198', 'Existe julgamento sobre pobreza, benefício, maternidade e informação, e a beneficiária muitas vezes sente que precisa se defender de estigmas.', 'mulheres beneficiárias', NULL, 'estigma do benefício', 'perfil', NULL, NULL, '36'), ('D12-TR-001-mb', 'A Mulher já vive no limite da decisão cotidiana.', 'mulheres beneficiárias', NULL, 'gênero e trabalho', 'perfil', NULL, NULL, '7'), ('D12-TR-003-mb', 'A rotina descrita combina cálculo do mês, negociação de tempo, cuidado dos filhos, trabalho dentro ou fora da formalidade e busca de informação por conta própria.', 'mulheres beneficiárias', NULL, 'gênero e trabalho', 'perfil', NULL, NULL, '7'), ('D12-TR-245-mb', 'O ponto de convergência entre as três macronarrativas é a passagem de um estado disfórico, marcado por sobrecarga, desconfiança, desamparo, deslegitimação ou desencanto, para um estado mais eufórico de potência, reconhecimento e possibilidade.', 'mulheres beneficiárias', NULL, 'autonomia e amparo', 'perfil', NULL, NULL, '41'), ('D12-TR-246-mb', 'A comunicação deve narrar essa transformação com a mulher no centro.', 'mulheres beneficiárias', NULL, 'comunicação e linguagem', 'perfil', NULL, NULL, '41'), ('D12-TR-247-mb', 'A mulher não apenas recebe proteção, participação ou pertencimento nacional: ela usa essas ferramentas para trabalhar sem se anular, decidir sem ser tutelada e voltar a acreditar em um Brasil possível.', 'mulheres beneficiárias', NULL, 'autonomia e amparo', 'perfil', NULL, NULL, '41'), ('D12-TR-248-mb', 'Em todas as macronarrativas, a mulher não aparece como destinatária passiva da comunicação, mas como sujeito competente: trabalha, cuida, decide, avalia, compara, desconfia, cobra e sustenta a vida cotidiana.', 'mulheres beneficiárias', NULL, 'reconhecimento do trabalho', 'perfil', NULL, NULL, '41'), ('D12-TR-249-mb', 'A força das macronarrativas está em transformar o "se virar sozinha" em suporte, voz e futuro possível.', 'mulheres beneficiárias', NULL, 'autonomia e amparo', 'perfil', NULL, NULL, '42'), ('D12-TR-253-mb', 'Abrir futuro sem negar o aperto: o horizonte precisa ser crível, com menos improviso no trabalho, mais segurança na decisão e possibilidade de voltar a acreditar sem apagar o cansaço atual.', 'mulheres beneficiárias', NULL, 'futuro possível', 'perfil', NULL, NULL, '42'), ('D01-TR-037', 'Para MEI, a queixa número um é a ausência de renda fixa: dias bons e ruins se alternam sem aviso, com a jornada dupla ainda presente.', 'mulheres de 2 a 5 salários mínimos', 'dinheiro no bolso', 'mei e trabalho autônomo', 'achado', 'indício', NULL, '18'), ('D01-TR-042-m25', 'O dinheiro aparece como falta ou sonho distante, mas deve ser narrado como retomada de controle.', 'mulheres de 2 a 5 salários mínimos', 'dinheiro no bolso', 'custo de vida', 'achado', 'indício', NULL, '20'), ('D01-TR-052-m25', 'A equação tempo igual a dinheiro pesa no cotidiano.', 'mulheres de 2 a 5 salários mínimos', 'dinheiro no bolso', 'jornada de trabalho', 'achado', 'indício', NULL, '22'), ('D03-TR-006-m25', '5,4% da população obteve renda nos últimos doze meses com alguma atividade online, como vendas, links de afiliados, revendas, visualização remunerada de vídeos ou atuação como ponto de coleta de lojas online.', 'mulheres de 2 a 5 salários mínimos', 'dinheiro no bolso', 'renda e sustento', 'achado', 'indício', NULL, '15'), ('D03-TR-074-m25', 'O combate às desigualdades e privilégios recebe 21,1% de avaliação ótima ou boa e 38,2% ruim ou péssima.', 'mulheres de 2 a 5 salários mínimos', 'dinheiro no bolso', 'desigualdade', 'achado', 'indício', NULL, '73'), ('D03-TR-075-m25', 'Custo de vida, poder de compra e economia é a área com pior avaliação da gestão federal: 16,0% ótima ou boa e 53,7% ruim ou péssima.', 'mulheres de 2 a 5 salários mínimos', 